@@ -0,0 +1,37 @@
+import { TokenRefresher } from './tokenRefresher';
+
+describe('TokenRefresher', () => {
+  beforeEach(() => {
+    jest.useFakeTimers();
+    jest.setSystemTime(new Date('2026-01-01T00:00:00Z'));
+  });
+  afterEach(() => {
+    jest.useRealTimers();
+  });
+
+  it('refreshes 60s before expiry', async () => {
+    const fetchToken = jest
+      .fn()
+      .mockResolvedValueOnce({ token: 'a', expiresInSec: 300 })
+      .mockResolvedValueOnce({ token: 'b', expiresInSec: 300 });
+    const r = new TokenRefresher(fetchToken);
+    await r.start();
+    expect(r.current()).toBe('a');
+
+    await jest.advanceTimersByTimeAsync(239_000);
+    expect(fetchToken).toHaveBeenCalledTimes(1);
+
+    await jest.advanceTimersByTimeAsync(2_000);
+    expect(fetchToken).toHaveBeenCalledTimes(2);
+    expect(r.current()).toBe('b');
+  });
+
+  it('stops refreshing after stop()', async () => {
+    const fetchToken = jest.fn().mockResolvedValue({ token: 'a', expiresInSec: 300 });
+    const r = new TokenRefresher(fetchToken);
+    await r.start();
+    r.stop();
+    await jest.advanceTimersByTimeAsync(600_000);
+    expect(fetchToken).toHaveBeenCalledTimes(1);
+  });
+});

