+import { runTurn } from './runTurn';
+import { TOOL_DEFS } from './tools';
+
+const create = jest.fn();
+const client = { messages: { create } } as any;
+
+beforeEach(() => {
+  create.mockReset();
+  create.mockResolvedValue({
+    stop_reason: 'end_turn',
+    content: [{ type: 'text', text: 'done' }],
+  });
+});
+
+it('sends system prompt, tool definitions and the user turn to the model', async () => {
+  await runTurn(client, { userText: 'close ticket t-1', tenantId: 'acme' });
+
+  expect(create).toHaveBeenCalledTimes(1);
+  const req = create.mock.calls[0][0];
+  expect(req.model).toBe('claude-sonnet-4-5');
+  expect(req.system).toContain('tenant: acme');
+  expect(req.tools.map((t: any) => t.name)).toEqual(TOOL_DEFS.map((t) => t.name));
+  expect(req.messages).toEqual([{ role: 'user', content: 'close ticket t-1' }]);
+});
+
+it('returns the text of the final assistant message', async () => {
+  const out = await runTurn(client, { userText: 'hi', tenantId: 'acme' });
+  expect(out.text).toBe('done');
+});
+
+it('does not send tools from other tenants', async () => {
+  await runTurn(client, { userText: 'hi', tenantId: 'acme' });
+  const names = create.mock.calls[0][0].tools.map((t: any) => t.name);
+  expect(names).not.toContain('admin_purge');
+});

