-}
+let cachedClient: AnthropicClient | undefined;
+
+export async function handleTicket(
+  ticket: Ticket,
+  doEmbed: boolean,
+  doNotify: boolean,
+  legacyFormat: boolean,
+  isRetry: boolean,
+) {
+  if (!cachedClient) cachedClient = new AnthropicClient(process.env.ANTHROPIC_API_KEY!);
+  const parsed = ticket.raw ? JSON.parse(ticket.raw) : ticket;
+  const saved = await repo.save(parsed);
+  if (doEmbed) {
+    const v = await cachedClient.embed(parsed.body);
+    await pool.query('UPDATE tickets SET embedding = $1 WHERE id = $2', [JSON.stringify(v), saved.id]);
+  }
+  if (doNotify) {
+    await sqs.send(new SendMessageCommand({
+      QueueUrl: process.env.NOTIFY_QUEUE_URL,
+      MessageBody: JSON.stringify({ id: saved.id, retry: isRetry }),
+    }));
+  }
+  let reply: string;
+  if (legacyFormat) {
+    reply = 'Ticket ' + saved.id + ' received on ' + new Date().toDateString();
+  } else {
+    reply = `Ticket ${saved.id} received`;
+  }
+  if (isRetry) {
+    await dynamo.send(new PutItemCommand({
+      TableName: 'ticket-retries',
+      Item: { id: { S: saved.id }, at: { S: new Date().toISOString() } },
+    }));
+  }
+  return { saved, reply };
+}
